// ValueUnit as a property value; defined beside ValueBar's table.
template <>
struct PropertyValueTraits<ValueUnit> {
    static PropertyType type();
    static BindingValue to_binding(ValueUnit value);
    static ValueUnit from_binding(const BindingValue& value);
};

// ValueBarStyle as a property value; defined beside ValueBar's table.
template <>
struct PropertyValueTraits<ValueBarStyle> {
    static PropertyType type();
    static BindingValue to_binding(ValueBarStyle value);
    static ValueBarStyle from_binding(const BindingValue& value);
};

// Every ValueBar capability, in the order the declaring class takes them.
template <typename Declaring>
struct ValueBarCapabilities : public ValueBarSoftMinimumCapability<Declaring>,
                              public ValueBarSoftMaximumCapability<Declaring>,
                              public ValueBarSnapStepCapability<Declaring>,
                              public ValueBarPrecisionCapability<Declaring>,
                              public ValueBarUnitCapability<Declaring>,
                              public ValueBarDefaultValueCapability<Declaring>,
                              public ValueBarPresentationCapability<Declaring>,
                              public ValueBarLabelCapability<Declaring>,
                              public ValueBarScrubRateCapability<Declaring> {};

